function enemyMarkup(raw){const e=getEnemyView(raw),isSelected=game.battle.targetId===e.id;return `<button class="enemy-card ${esc(e.kind)} ${isSelected?'selected':''} ${e.defeated?'dead':''}" data-target="${esc(e.id)}" ${e.defeated?'disabled':''} aria-label="選擇${esc(e.name)}${isSelected?'，目前目標':''}" aria-pressed="${isSelected}"><span class="target-caret">◆</span>${ui.feedback.filter(f=>f.targetId===e.id&&f.amount).map(f=>`<span class="damage-float ${f.critical?'critical':''}">${f.critical?'CRIT'+(f.criticalHits?' ×'+esc(f.criticalHits):'')+' ':f.glancing?'GLANCE ':''}−${esc(f.amount)}</span>`).join('')}${e.scanned?'<span class="scan-badge">已探查</span>':''}<span class="enemy-sprite ${esc(e.kind)}"><img src="./public/assets/twilight-enemies.png" alt="" draggable="false"></span><span class="enemy-name">${esc(e.name)}</span><span class="enemy-level">${e.scanned?`LV. ${esc(e.level)}`:'LV. ??'} · ${esc(e.title)}</span><span class="enemy-health"><span class="bar" style="display:block"><span class="bar-fill" style="display:block;width:${esc(e.hpPercent)}%"></span></span><small>${e.scanned?`${esc(e.hp)} / ${esc(e.maxHp)}`:e.defeated?'已擊倒':`${esc(e.hpPercent)}% HP`}</small></span><span class="enemy-tooltip">${e.scanned?`生命 ${esc(e.hp)} / ${esc(e.maxHp)}<br>物理抗性 ${Math.round(e.resistances.physical*100)}% · 火焰 ${Math.round(e.resistances.fire*100)}%`:'使用「探查」取得等級、精確生命與抗性'}<br>不顯示未來敵方行動</span></button>`}
