function trainingDuration(ms){
  if(!Number.isFinite(ms))return '—';
  const seconds=Math.max(0,Math.ceil(ms/1000));
  return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':');
}
function trainingDate(ms){
  return Number.isSafeInteger(ms)?new Date(ms).toLocaleString('zh-TW',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZoneName:'short'}):'—';
}
function trainingClockState(q){return q.ok?`${q.revision}:${q.status}:${q.activeBattle}:${historyUpgradePending}:${!!ui.modal}`:`error:${q.code}`;}
function trainingCandidateNotice(warning=TRAINING_POLICY.candidateWarning){
  return `<section class="training-boundary"><h3>來源與候選邊界</h3><p>${esc(warning)}</p><p>每階 +${esc(TRAINING_POLICY.expBonusPercentPerRank)}% EXP、${esc(TRAINING_POLICY.durationMs/3600000)} 小時與 ${esc(TRAINING_POLICY.maxRank)} 階上限有公開記錄。價格採印出的公式：首階 100 Credits；公式末階為 49,999，表列 50,000；總價也有 2 Credits 差異，尚未原服核實。</p><p>本原型選擇營地限定開始／取消／領取，並於下一個戰鬥系列套用已領取階級；到期未領取也不可退款。這些啟用與退款邊界是保守候選，並非已驗證的原服行為。EXP 先套用加成再依每波候選規則取整。</p><div class="training-source-links"><a href="${esc(TRAINING_POLICY.sources.training)}" target="_blank" rel="noopener">Training 來源 ↗</a><a href="${esc(TRAINING_POLICY.sources.experience)}" target="_blank" rel="noopener">EXP 來源 ↗</a><a href="./docs/TRAINING-LEDGER.md" target="_blank" rel="noopener">本機帳本與差異 ↗</a></div></section>`;
}
function trainingContents(q){
  if(!q.ok)return `<section class="panel training-unavailable"><div class="eyebrow">THE STUDY IS QUIET</div><h2>研習尚不可用</h2><p role="status">${esc(q.error)}</p><p>目前僅開放 EXP 帳本角色的 Adept Learner；舊角色不會自動改配或獲得免費階級。</p><button class="subtle-button" data-cmd="settings">檢視存檔設定</button></section>${trainingCandidateNotice()}`;
  const job=q.active,readOnly=historyUpgradePending,stateLabel={idle:'等待研習',training:'研習進行中',ready:'到期 · 等待領取',capped:'已達最高階'},progress=job?Math.min(100,Math.max(0,(TRAINING_POLICY.durationMs-q.remainingMs)/TRAINING_POLICY.durationMs*100)):0;
  const blocked=q.activeBattle?'戰鬥系列尚未結束，包含波次等待；請結束整場後回營地。':readOnly?'目前僅供檢視，請先確認舊檔保存格式。':q.nextCost!==null&&q.credits<q.nextCost?'Credits 不足，可從競技場或 Grindfest 通關取得。':q.status==='capped'?'已完成全部階級，無須再支付 Credits。':'每次只研習一階，確認後才扣款並開始計時。';
  const readyHint=q.activeBattle?'研習時間已到；整個戰鬥系列結束後，再回到 Training 領取。':readOnly?'研習時間已到；目前為唯讀，完成保存格式確認後才能領取。':ui.modal?'研習時間已到；關閉目前的確認視窗後，會在此頁領取一次。':'研習時間已到，回到此頁即可領取這一階。';
  const last=game.training.lastAction;
  return `${ui.trainingNotice?`<div class="training-notice" role="status">${esc(ui.trainingNotice)}</div>`:''}${ui.saveError?`<div class="training-error" role="alert">${esc(ui.saveError)}。目前顯示的是此分頁中的進度。</div>`:''}<div class="training-layout"><section class="panel training-study"><div class="training-intro"><div class="training-seal" aria-hidden="true">${icon('book')}<span>✧</span></div><div><div class="eyebrow">ADEPT LEARNER</div><h2>精進研習</h2><p>燈火不息，所學漸深。每完成一階，<br>往後戰鬥獲得的 EXP 增加 ${esc(TRAINING_POLICY.expBonusPercentPerRank)}%。</p></div><span class="tag ${q.status==='ready'?'gold':''}">${esc(stateLabel[q.status])}</span></div><div class="training-benefit"><div><small>已完成階級</small><strong>${esc(q.adeptRank)} <em>/ ${esc(q.maxRank)}</em></strong></div><div><small>已取得 EXP 加成</small><strong>+${esc(q.expBonusPercent)}<em>%</em></strong><span>${statText(q.expMultiplier)}× · 僅 Adept 部分</span></div></div><div class="training-order">${job?`<div class="training-order-heading"><div><div class="eyebrow">ONE ACTIVE LESSON</div><h3>第 ${esc(job.fromRank+1)} 階研習</h3></div>${icon(q.readyToComplete?'check':'clock')}</div><div class="training-clock ${q.readyToComplete?'ready':''}"><small>${q.readyToComplete?'已到期，尚未取得階級':'距離研習完成'}</small><strong id="training-countdown" role="timer" aria-live="off" aria-label="研習剩餘時間">${esc(trainingDuration(q.remainingMs))}</strong><span>${q.readyToComplete?'READY TO COLLECT':'REAL TIME · 不使用戰鬥回合'}</span></div><div class="training-progress" id="training-progress" role="progressbar" aria-label="研習時間進度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${esc(Math.floor(progress))}"><span style="width:${esc(progress)}%"></span></div><dl class="training-dates"><div><dt>開始</dt><dd>${esc(trainingDate(job.startedAt))}</dd></div><div><dt>到期</dt><dd>${esc(trainingDate(job.endsAt))}</dd></div><div><dt>已支付</dt><dd>${statText(job.paidCredits)} Credits</dd></div></dl><p class="training-status" role="status">${q.readyToComplete?esc(readyHint):'離開頁面、關閉或重新載入都保留同一到期時間。可繼續戰鬥；等待不會自行推進戰鬥，也不發 EXP。'}</p><div class="training-actions">${q.readyToComplete?`<button class="primary-button" data-cmd="training-collect" ${q.canCollect&&!readOnly&&!ui.modal?'':'disabled'}>${icon('check')}領取已完成研習</button>`:`<button class="subtle-button" data-cmd="training-cancel-review" ${q.canCancel&&!readOnly?'':'disabled'}>檢查取消與全額退款</button>`}${q.activeBattle?'<button class="subtle-button" data-nav="battle">返回未結束的戰鬥</button>':''}</div>${!q.readyToComplete&&q.activeBattle?`<p class="training-gate">${esc(blocked)}</p>`:''}<p class="training-gate">到期前取消可退回實付 ${statText(job.paidCredits)} Credits；到期起不可退款。沒有加速、隊列或自動續訓。</p>`:`<div class="training-order-heading"><div><div class="eyebrow">${q.status==='capped'?'A LESSON WELL LEARNED':'THE NEXT LESSON'}</div><h3>${q.status==='capped'?'研習圓滿':`研習第 ${esc(q.adeptRank+1)} 階`}</h3></div>${icon(q.status==='capped'?'star':'clock')}</div>${q.nextCost!==null?`<div class="training-price"><span>下一階費用 <small>價格公式候選</small></span><strong>${statText(q.nextCost)} <small>Credits</small></strong></div><div class="training-next"><span>實時 ${esc(TRAINING_POLICY.durationMs/3600000)} 小時</span><span>領取後 +${esc(q.expBonusPercent+TRAINING_POLICY.expBonusPercentPerRank)}% EXP</span></div><button class="primary-button" data-cmd="training-start-review" ${q.canStart&&!readOnly?'':'disabled'}>${icon('book')}檢查研習明細</button>`:'<p class="training-cap">已完成 Adept Learner 全部階級。已取得的加成保留，不提供重置退款。</p>'}<p class="training-status" role="status">${esc(blocked)}</p><p class="training-gate">目前餘額 ${statText(q.credits)} Credits。研習不贈送 Credits、EXP 或其他道具。</p>`}</div>${last?.type==='cancel'?`<div class="training-receipt">最近一次取消：退回實付 ${statText(last.paidCredits)} Credits · ${esc(trainingDate(last.at))}</div>`:''}</section><aside class="training-notebook"><section class="panel training-contract"><div class="eyebrow">KEEP A LIGHT BURNING</div><h3>燈火下的約定</h3><ol><li><strong>支付一階的費用</strong><span>只使用挑戰所得的遊戲內 Credits；確認才開始。</span></li><li><strong>等待一小時</strong><span>以已保存的本機時鐘到期時間計算。離線仍計時；一時只能有一項研習。</span></li><li><strong>回到 Training 領取</strong><span>離開此頁時，單純到期不加階級；在營地開著此頁時會於到期安全領取一次。</span></li></ol><p>完成領取後，永久加成自下一個戰鬥系列生效。研習本身不會立即增加 EXP。</p></section><section class="training-deferred"><span>${icon('lock')}</span><div><h3>其餘書卷尚未開放</h3><p>Ability Boost 與其他 Training 延後接入；沒有 AP 購買或替代免費加成。</p></div></section></aside></div>${trainingCandidateNotice(q.warning)}`;
}
function trainingView(nowMs=Date.now()){
  const q=getTrainingView(game,nowMs);
  return `${heading('THE LAMPLIT STUDY','營地研習','將挑戰所得，積累為長久的學識',`<span class="version-tag">Training · 候選帳本</span>`)}<div id="training-view" data-clock-state="${esc(trainingClockState(q))}">${trainingContents(q)}</div>`;
}
/** A page visit may settle one job; drawing the remaining time never saves. */
function visitTrainingIfReady(nowMs){
  if(ui.view!=='training'||ui.modal||historyUpgradePending||!prefs.onboarded||active())return false;
  const q=getTrainingView(game,nowMs);
  if(!q.ok||!q.canCollect)return false;
  const result=visitTraining(game,nowMs);
  if(!result.ok){if(ui.trainingError!==result.error)toast(result.error);ui.trainingError=result.error;return false;}
  if(!result.changed)return false;
  const saved=persist();
  ui.trainingNotice=saved?`第 ${result.adeptRank} 階研習已領取；+${result.adeptRank}% EXP 將套用之後開始的戰鬥系列。`:'';
  toast(saved?ui.trainingNotice:ui.saveError);
  return true;
}
function refreshTrainingClock(){
  if(ui.view!=='training')return;
  const nowMs=Date.now();
  if(visitTrainingIfReady(nowMs)){render();return;}
  const root=$('#training-view');if(!root)return;
  const q=getTrainingView(game,nowMs),state=trainingClockState(q);
  if(root.dataset.clockState!==state){
    const focused=document.activeElement,command=root.contains(focused)?focused?.dataset?.cmd:null;
    root.innerHTML=trainingContents(q);root.dataset.clockState=state;
    if(command)[...root.querySelectorAll('button[data-cmd]')].find(button=>button.dataset.cmd===command&&!button.disabled)?.focus({preventScroll:true});
    return;
  }
  if(!q.ok||!q.active)return;
  const countdown=$('#training-countdown');if(countdown)countdown.textContent=trainingDuration(q.remainingMs);
  const progress=$('#training-progress'),percent=Math.min(100,Math.max(0,(TRAINING_POLICY.durationMs-q.remainingMs)/TRAINING_POLICY.durationMs*100));
  if(progress){progress.setAttribute('aria-valuenow',String(Math.floor(percent)));if(progress.firstElementChild)progress.firstElementChild.style.width=percent+'%';}
}
function trainingModal(){
  const q=ui.pendingTraining;if(!q)return '<h2>研習明細已失效</h2><p>請關閉後重新檢查。</p>';
  const cancel=q.kind==='cancel',job=q.active;
  return `<div class="eyebrow">${cancel?'CANCEL THIS LESSON':'BEGIN ONE LESSON'}</div><h2>${cancel?'取消這次研習？':`開始第 ${esc(q.toRank)} 階研習？`}</h2>${cancel?`<div class="notice-box">取消第 ${esc(job.fromRank+1)} 階研習<br>退回當時實付的 ${statText(job.paidCredits)} Credits<br>原到期時間：${esc(trainingDate(job.endsAt))}</div><p class="training-modal-note">只有確認時仍早於到期時間才能退款。取消不增加階級；之後重新開始須重新付費、完整等待一小時。</p><p class="training-modal-note">如果在此視窗等待至到期，退款會被拒絕。關閉視窗後回到 Training 領取；到期或已領取的研習皆不可退款。</p>`:`<div class="notice-box">Adept Learner：${esc(q.fromRank)} → ${esc(q.toRank)} 階<br>費用 ${statText(q.cost)} Credits · 實時 ${esc(q.durationMs/3600000)} 小時<br>已取得加成 ${statText(q.expMultiplierBefore)}× → 領取後 ${statText(q.expMultiplierAfter)}× EXP<br>預計到期：${esc(trainingDate(q.endsAt))}</div><p class="training-modal-note">確認時會重新核對價格與資格，從按下確認的實際時間開始計時。預計到期只供參考；真正到期時間會記入存檔。</p><p class="training-modal-note">只有一項研習，不會排入下一階或自動續訓。到期前取消可全額退款，到期起不可退款。結束戰鬥系列後回到此頁領取，再於後續系列生效。</p><p class="training-modal-note">價格公式與啟用邊界為明示候選；研習不立即發 EXP，Ability Boost 尚未開放。</p>`}${ui.trainingError?`<p class="training-error" role="alert">${esc(ui.trainingError)}</p>`:''}<div class="modal-footer training-modal-footer"><button class="subtle-button" data-cmd="close-modal">${cancel?'保留研習並返回':'先不開始'}</button>${ui.trainingError?'<button class="subtle-button" data-cmd="training-refresh">重新檢查明細</button>':''}<button class="${cancel?'danger-button':'primary-button'}" data-cmd="${cancel?'training-cancel-confirm':'training-start-confirm'}" ${ui.trainingError?'disabled':''}>${cancel?`確認取消，退回 ${statText(job.paidCredits)} Credits`:`確認支付 ${statText(q.cost)} Credits 並開始`}</button></div>`;
}
function trainingFailure(error){ui.trainingError=error||'目前無法執行研習';renderModal();toast(ui.trainingError);}
function reviewTraining(kind){
  if(historyUpgradePending){openModal('audit-upgrade');return;}
  const nowMs=Date.now(),view=getTrainingView(game,nowMs);
  if(!view.ok){trainingFailure(view.error);return;}
  if(kind==='start'){
    const q=quoteAdeptTraining(game,nowMs,view.revision);
    if(!q.ok){trainingFailure(q.error);return;}
    ui.pendingTraining={...q,kind:'start'};
  }else{
    if(!view.canCancel){trainingFailure(view.readyToComplete?'Training 已到期，不可退款；請關閉視窗並回到 Training 領取':view.activeBattle?'戰鬥中與波次暫停時不能取消 Training':'目前沒有可取消的 Training');return;}
    ui.pendingTraining={kind:'cancel',expectedRevision:view.revision,active:{...view.active}};
  }
  ui.trainingError='';openModal(kind==='start'?'training-start':'training-cancel');
}
function finishTrainingAction(result,message){
  if(!result.ok){trainingFailure(result.error);return;}
  const saved=!result.changed||persist();
  closeModal();ui.trainingNotice=saved?message:'';render();
  toast(saved?(result.duplicate?'此筆研習操作已處理，沒有重複扣款或退款':message):ui.saveError);
}
function confirmTrainingStart(){
  const q=ui.pendingTraining;if(ui.modal!=='training-start'||q?.kind!=='start'||ui.trainingError||historyUpgradePending)return;
  const nowMs=Date.now(),fresh=quoteAdeptTraining(game,nowMs,q.expectedRevision);
  if(!fresh.ok){trainingFailure(fresh.error);return;}
  const fields=['id','costModel','expectedRevision','fromRank','toRank','cost','durationMs','expMultiplierBefore','expMultiplierAfter'];
  if(fields.some(key=>fresh[key]!==q[key])){trainingFailure('價格、資格或階級已變更，請重新檢查明細');return;}
  const result=startAdeptTraining(game,nowMs,q.expectedRevision);
  finishTrainingAction(result,`已支付 ${q.cost} Credits，開始第 ${q.toRank} 階研習。到期後回到 Training 領取。`);
}
function confirmTrainingCancel(){
  const q=ui.pendingTraining;if(ui.modal!=='training-cancel'||q?.kind!=='cancel'||ui.trainingError||historyUpgradePending)return;
  const nowMs=Date.now(),view=getTrainingView(game,nowMs);
  if(!view.ok){trainingFailure(view.error);return;}
  if(view.revision!==q.expectedRevision||!view.active||['id','fromRank','paidCredits','startedAt','endsAt'].some(key=>view.active[key]!==q.active[key])){trainingFailure('Training 版本或研習內容已變更，請重新檢查明細');return;}
  const result=cancelAdeptTraining(game,nowMs,q.expectedRevision);
  finishTrainingAction(result,`已取消研習，退回實付 ${q.active.paidCredits} Credits；已完成階級維持不變。`);
}

function vitalModelNotice(){const stats=getStats(game),legacy=game.vitalRules===VITAL_POLICY.legacy;return `<section class="vital-model-note"><div><div class="eyebrow">${legacy?'PRESERVED LEGACY VITALS':'SOURCED VITALS CANDIDATE'}</div><h3>${legacy?'資源上限保留舊版樣本':'資源上限採來源候選式'}</h3><p>${legacy?'更新未更動既有 HP／MP／SP。可在戰外預覽，再決定是否採用新的公開公式。':'HP = 500 + 10×等級 + 6×體質；MP = 10 + 等級 + 感知；SP = 1 + 六屬性總和/5。套用已裝配 Tank 後最終向下取整，原服取整仍待驗證。'}</p><div class="vital-model-values">${[['Hp','HP'],['Mp','MP'],['Sp','SP']].map(([key,label])=>`<span>${label} <strong>${stats['base'+key]}</strong> 基礎 → <strong>${stats['max'+key]}</strong> 上限</span>`).join('')}</div></div><div>${legacy?`<button class="subtle-button" data-cmd="vitals-review" ${active()?'disabled':''}>預覽來源模型</button>`:''}<a href="./docs/VITALS.md" target="_blank" rel="noopener">公式與相容政策 ↗</a></div></section>`;}
function characterTabs(){return `<div class="character-tabs"><button class="${ui.characterTab==='attributes'?'active':''}" data-character-tab="attributes">${icon('person')}屬性與 EXP</button><button class="${ui.characterTab==='abilities'?'active':''}" data-character-tab="abilities">${icon('star')}能力配置</button></div>`;}
function abilityCard(def){
  const a=game.abilities,summary=getAbilitySummary(game),stats=getStats(game),supportive=def.slotType==='supportive',slots=supportive?a.supportiveSlots:a.majorSlots,rank=a.purchased[def.id],slot=slots.indexOf(def.id),empty=slots.indexOf(null),next=def.ranks[rank],q=quoteAbilityPurchase(game,def.id),names={hp:'生命容量',mp:'魔力容量',sp:'靈力容量'};
  const preview=supportive?`<span>目前 Cure ${getCureProfile(game).amount} HP</span><strong>冷卻 ${getCureProfile(game).cooldown} 行動</strong>`:`<span>基礎 ${stats['base'+def.pool[0].toUpperCase()+def.pool.slice(1)]}</span><strong>上限 ${stats['max'+def.pool[0].toUpperCase()+def.pool.slice(1)]}</strong>`;
  return `<section class="panel ability-card ${slot>=0?'slotted':''}"><div class="ability-symbol ${supportive?'supportive':def.pool}">${icon(supportive?'heart':{hp:'heart',mp:'drop',sp:'spark'}[def.pool])}</div><div class="eyebrow">${esc(def.name)}</div><h2>${supportive?'強化治癒':names[def.pool]}</h2><p>${supportive?'装配後採來源治療候選式與較短冷卻。<br>熟練度固定為 0 樣本，成長尚未接入。':'每階增加 10% 上限。<br>只有裝配後才生效；不提高藥水的基礎計算值。'}</p><div class="ability-rank"><strong>${rank?'已學習 '+rank+' 階':'尚未學習'}</strong><span>${slot>=0?'生效於 '+(supportive?'Supportive':'Major')+' '+(slot+1):rank?'尚未裝配':'無效果'}</span></div><div class="ability-preview">${preview}</div><button class="primary-button" data-ability-buy="${esc(def.id)}" ${q.ok?'':'disabled'} title="${esc(q.error||'學習後仍須裝配')}">${next?'學習 '+(rank+1)+' 階 · '+next.cost+' AP':'後續階級待施工'}</button><small class="ability-gate">${next?'此階需要 Lv.'+Math.max(1,next.minLevel):'本次只接入前兩階，並非原版最高階'}${supportive?'；Cure 施放須 Lv.5':''}</small><div class="ability-actions"><button class="subtle-button" data-ability-slot="${esc(def.id)}" ${!summary.enabled||active()||!rank||slot>=0||empty<0?'disabled':''}>${slot>=0?'已裝配':'裝入 '+(supportive?'綠色':'Major')+' 空槽'}</button><button class="subtle-button" data-ability-reset="${esc(def.id)}" ${!summary.enabled||active()||!rank||!summary.freeSingleResetsRemaining?'disabled':''}>單項重置</button></div></section>`;
}
function abilitySlots(family){const slots=game.abilities[family+'Slots'],label=family==='major'?'Major':'Supportive';return `<section class="panel ability-slots ${family}"><div class="sheet-heading"><h2>${label} 能力槽</h2><span class="tag">${slots.filter(Boolean).length} / 5</span></div><div class="major-slots">${slots.map((id,index)=>`<div class="major-slot ${id?'occupied':''}"><small>${label.toUpperCase()} ${index+1}</small><strong>${id?esc(ALL_ABILITIES[id].name):'空槽'}</strong>${id?`<button class="subtle-button" data-ability-unslot="${index}" data-ability-unslot-family="${family}" ${active()?'disabled':''}>卸下</button>`:'<span class="muted">學習後可裝配</span>'}</div>`).join('')}</div></section>`;}
function abilitiesView(){const a=game.abilities,summary=getAbilitySummary(game),enabled=summary.enabled;return `${heading('THE INNER CONSTELLATION','能力配置','先學習，再裝配到能力槽',`<span class="version-tag">AP 候選帳本</span>`)}${characterTabs()}${vitalModelNotice()}<div class="ability-summary"><div><small>可用 AP</small><strong>${summary.unspentAP}</strong></div><div><small>已投入 / 總 AP</small><strong>${summary.spentAP} <em>/ ${summary.totalAP}</em></strong></div><div><small>Mastery 資格</small><strong>${summary.masteryPoints}</strong></div><div><small>免費單項重置</small><strong>${summary.freeSingleResetsRemaining} <em>/ ${enabled?10:0}</em></strong></div></div>${active()?'<div class="arena-notice">戰鬥系列尚未結束；包含波次等待，學習、裝配、卸下及重置皆暫停。</div>':''}${!enabled?'<div class="notice-box">舊版演練角色保留原有點數模型；沒有把屬性點轉成 AP。能力帳本適用 EXP 配置角色。</div>':''}<div class="ability-grid">${Object.values(ALL_ABILITIES).map(abilityCard).join('')}</div>${abilitySlots('major')}${abilitySlots('supportive')}<p class="workbench-note">卸下只停止效果，不返還 AP。免費單項重置次數採公開文字的 10 次候選；付費重置／Mastery 擴槽／完整樹尚未開放。Better Cure 的效力 70／85，於明示熟練度 0 時，分別治療 56%／68% 基礎 HP；未裝配的 Cure 保留舊治療樣本，來源模型未保證較該樣本更高。</p><p class="ability-fidelity">總 AP 採每等級 1 點，含推定的 Lv.1 初始點；Mastery 每 10 級 1 點。舊升級紀錄不會再加算一次。${game.vitalRules===VITAL_POLICY.legacy?'基礎資源保留舊版樣本':'基礎資源採來源候選式'}，最終取整尚未原服驗證。沒有訓練或外部權益 AP。 <a href="./docs/ABILITIES.md" target="_blank" rel="noopener">來源與政策 ↗</a></p>`;}

function characterView(){if(ui.characterTab==='abilities')return abilitiesView();const p=game.player,s=getStats(game),ledger=game.progression?.kind==='experience-ledger'?game.progression:null,step=ledger?ui.attributeStep:1;return `${heading('THE WAYFARER','旅者檔案','把經驗配置到你選擇的戰鬥方式',`<span class="version-tag">PERSISTENT</span>`)}${characterTabs()}${vitalModelNotice()}<div class="character-layout"><aside class="panel character-card"><div class="portrait-frame">${portrait()}</div><h2>${esc(p.name)}</h2><div class="eyebrow">LEVEL ${p.level} · WAYFARER</div><p>穿越暮色，踏入裂隙。<br>你的下一步，仍由自己決定。</p><div class="tags"><span class="tag">${ledger?'EXP 配置候選規格':'舊版演練角色'}</span><span class="tag">無原站加成</span></div><button class="subtle-button" data-nav="armory">${icon('shield')}前往裝備工作台</button></aside><section class="panel sheet-panel"><div class="sheet-heading"><h2>基礎屬性</h2>${ledger?`<label class="attribute-step-label">每次調整 <select id="attribute-step" aria-label="每次調整屬性點數">${[1,10,100].map(n=>`<option value="${n}" ${step===n?'selected':''}>${n} 點</option>`).join('')}</select></label>`:`<span class="tag gold">舊版點數 ${p.attributePoints}</span>`}</div>${ledger?`<div class="experience-summary"><div><small>累計 EXP</small><strong>${ledger.earned.toLocaleString()}</strong></div><div><small>已配置 EXP</small><strong>${ledger.allocated.toLocaleString()}</strong></div><div><small>可用 EXP</small><strong class="gold">${ledger.unspent.toLocaleString()}</strong></div></div><div class="experience-track"><div><span>Lv.${p.level} → ${p.level<500?p.level+1:'MAX'}</span><span>${(p.xp-experienceThreshold(p.level)).toLocaleString()} / ${Math.max(0,p.xpNext-experienceThreshold(p.level)).toLocaleString()} EXP</span></div><div class="bar"><div class="bar-fill" style="width:${p.level===500?100:Math.min(100,100*(p.xp-experienceThreshold(p.level))/(p.xpNext-experienceThreshold(p.level)))}%"></div></div></div>`:''}<div class="attribute-grid">${Object.entries(attrs).map(([key,[name,en,ico]])=>{const plus=getAttributeQuote(game,key,step),minus=ledger?getAttributeQuote(game,key,-step):null;return `<div class="attribute-wrap"><div class="attribute">${icon(ico)}<span>${name}<small>${en}</small></span><strong>${p.attributes[key]}</strong>${ledger?`<button class="subtract" data-attribute="${key}" data-delta="${-step}" aria-label="降低${name}${step}點" title="${esc(active()?'戰鬥中不能配置或返還屬性':minus.ok?'返還 '+(-minus.cost)+' EXP':minus.error)}" ${active()||!minus.ok?'disabled':''}>−</button>`:''}<button data-attribute="${key}" data-delta="${step}" aria-label="提高${name}${step}點" title="${esc(active()?'戰鬥中不能配置或返還屬性':plus.ok?ledger?'配置 '+plus.cost+' EXP':'使用一點舊版演練點數':plus.error)}" ${active()||!plus.ok?'disabled':''}>+</button></div>${ledger?`<div class="attribute-cost"><span>${minus.cost!==undefined?'−'+step+' 返還 '+(-minus.cost).toLocaleString():'此步幅會超過下限'}</span><span class="${plus.ok?'':'unaffordable'}">${plus.cost!==undefined?'＋'+step+' 需 '+plus.cost.toLocaleString()+' EXP':'超出候選範圍'}</span></div>`:''}</div>`}).join('')}</div><p class="attribute-note">${ledger?'公開 EXP 配置公式，採集中式「累計值向上取整」候選政策；取整、返還與上下限尚未原服驗證。配置或返還不改累計 EXP／角色等級。初始 9,193 EXP 與六項 14 為明示起始設定；演練不發 EXP。':'既有角色的屬性與剩餘演練點數完整保留，沒有自動重配或補发 EXP。新建立的角色採可檢查的 EXP 配置帳本。'} <a href="./docs/PROGRESSION.md" target="_blank" rel="noopener">公式與假設 ↗</a></p><div class="regen-reference">新戰鬥每 tick：MP +${naturalRegenRates(p.attributes).mp.toFixed(2)} / SP +${naturalRegenRates(p.attributes).sp.toFixed(2)}<br><small>公開公式，分數累積取整為明示候選；資源上限依本角色所選模型</small></div><div class="derived-grid">${[['物攻基值',s.attack.toFixed(2)],['魔攻基值',s.magic.toFixed(2)],['防禦（樣本）',s.defense],['對抗成功率樣本',s.accuracy+'%'],['攻速加成',s.speed+'%'],['負重',s.burden]].map(([l,n])=>`<div class="derived-stat"><small>${l}</small><strong>${n}</strong></div>`).join('')}</div><p class="workbench-note">物攻／魔攻基值與暴擊堆疊採公開候選規則。對抗成功率是原創樣本，不是原版 Accuracy 屬性：兩次成功才可暴擊，一次成功為半傷擦傷；最多9重、每重+50%。真正的準確度對抗／格擋／招架／抵抗尚未接入。EXP 獲取、升級、熟練度、AP／Mastery、Persona、稱號與完整流派持續施工；此頁與前三項競技場已接通 EXP 獲取／配置；能力頁已接入三種 Tank 與 Better Cure 的學習／裝配及受限重置；熟練度及其餘能力仍待施工。</p></section></div>`;}

const systems=[['角色與流派','六屬性、EXP、熟練度、AP／Mastery、Persona、稱號、全武器護甲流派','樣本可用','Character_Stats'],['戰鬥核心','三種時間尺度、資源、手動指令、Scan；全法術、狀態、連鎖與保命順序待補齊','部分可用','Action_Speed'],['裝備與改造','品質、roll、詞綴、綁定、等級縮放、IW、Forge、Charms、Pouches、Fusion、維修拆解','樣本可用','The_Armory'],['活動與時間','前三項 Arena 與 Grindfest 全 1,000 波、共享體力、候選 EXP／Credits 已接入；Grindfest 怪物與傷害為候選，一般／Crystal 掉落、Boss、RiddleMaster 待施工','部分可用','Arena'],['世界服務','Health Potion 與 Soul Fragment NPC 補給已開放；Adept Learner 已接入付費一小時研習候選；其他 Training、Bazaar、Market、MoogleMail／CoD、Shrine、Lottery、Monster Lab 持續施工','部分可用','The_Market'],['原站連動接口','GP、Hath、捐贈、論壇／圖庫觸發目前停用；不提供假補償，不憑空授予資格','停用','Hath_Perks'],['Persistent 長期養成','稱號、收藏、Perks、事件及玩家怪物材料循環；來源未核對則不啟用','未施工','Monster_Lab'],['Isekai 與賽季','獨立模式、Tower、排行榜、重置及跨模式轉移；依要求延後，仍保留規格','延後','Isekai']];
function rulesView(){return `${heading('THE RULES ATLAS','規則與施工圖譜','每一條差異，都應該能被看見',`<a class="subtle-button" href="./docs/RULES.md" target="_blank" rel="noopener">${icon('book')}完整規則帳</a>`)}<section class="panel rules-intro">${icon('info')}<div><h2>Persistent 0.91 是目標，不是已完成的承諾</h2><p>目前可驗證的是「手動戰鬥 → 裝備比較 → 調整角色 → 保存重開」原型。演練怪物、裝備、傷害及部分技能採暫定值；測試通過表示符合已記錄規格，不代表與原伺服器 1:1。沒有真實玩家、市場、離線收益或原站帳號連動。</p></div></section><div class="ledger-grid">${systems.map(([name,text,status,page])=>`<section class="panel ledger-card"><h3>${name}<span class="tag ${status.includes('可用')?'gold':''}">${status}</span></h3><p>${text}</p><a href="https://ehwiki.org/wiki/${page}" target="_blank" rel="noopener">社群文件來源 ↗</a></section>`).join('')}</div><section class="panel ledger-card" style="margin-top:13px"><h3>仍需釐清的核心衝突</h3><p>Defend 回血 10% / 25%、First Blood 波數、Item World 傷害增幅、Fiery Blast 消耗範例、怪物暴擊與新版裝備縮放。演練採用值和待驗證項目記錄於 <a href="./docs/RULES.md" target="_blank" rel="noopener">RULES</a>；完整分期記錄於 <a href="./docs/BACKLOG.md" target="_blank" rel="noopener">BACKLOG</a>。外部接口維持無加成，Isekai 延後。</p></section>`}
function activitiesView(){const views=previewActivities(game.activities,game.player.level,Date.now()),ledger=game.progression?.kind==='experience-ledger',stamina=views[0]?.stamina??game.activities.stamina;return `${heading('PATHS THROUGH THE RIFT','競技場與生存挑戰','選擇今日的旅程，按自己的步調繼續',`<span class="version-tag">體力 ${esc(stamina.toFixed(2))} / 99</span>`)}<div class="arena-notice">${icon('clock')}Arena 每日次數於 UTC 00:00 重置，入場即記次；Grindfest 沒有每日入場限制。兩者共用體力，每小時恢復 1。使用本機時鐘，未宣稱線上公平或防作弊。</div>${!ledger?`<div class="notice-box">此角色沿用舊版演練點數，完整保留既有進度。獎勵活動需要 EXP 帳本新角色；可先在設定匯出備份，再決定是否重開。原演練仍可使用。 <button class="subtle-button" data-cmd="settings">存檔設定</button></div>`:''}${grindfestActivityMarkup()}<div class="activity-section-heading"><h2>每日競技場</h2><span class="muted">各 1 次 / UTC 日</span></div><div class="activities-grid arena-cards">${views.map(a=>{const can=ledger&&a.eligible&&!active();return `<section class="panel activity-card ${can?'available':''}">${icon(can?'sword':'lock')}<div class="eyebrow">ARENA · LV.${a.minLevel}</div><h2>${a.name}</h2><p>${a.rounds} 波 · 共 ${a.monsterCount} 隻<br>每波數量：${a.roundCounts.join(' / ')}<br>${a.clears?'再次通關':'首次通關'} ${a.nextCredits.toLocaleString()} Credits + 1 件樣本池裝備</p><div class="arena-card-bottom"><button class="${can?'primary-button':'subtle-button'}" data-arena="${a.id}" ${can?'':'disabled'}>${can?'進入挑戰':active()?'目前戰鬥未結束':!ledger?'需 EXP 新角色':a.attemptedToday?'今日已使用':'尚未開放'} ${icon('arrow')}</button><small>${can?'每日 1 次':active()?'返回戰鬥以繼續':!ledger?'舊角色未被自動重配':esc(a.reason)}</small></div></section>`}).join('')}</div><p class="activity-fidelity">來源波次、次數與 Credits 規則已接入；怪物數值／PL100 與裝備模板／品質權重與數值投影為明示樣本；新系列掉落採逐項品質 roll。EXP 每波取整仍屬候選；一般隨機掉落、Token 與 RiddleMaster 尚未接入。 <a href="./docs/ARENA.md" target="_blank" rel="noopener">規則與差異 ↗</a></p><div class="activity-section-heading"><h2>演練與其他旅程</h2><span class="muted">完整系統持續施工</span></div><div class="activities-grid"><section class="panel activity-card available">${icon('sword')}<div class="eyebrow">UNREWARDED PRACTICE</div><h2>裂隙演練</h2><p>2 波 × 3 隻原創敵人。驗證裝備和操作，不消耗每日競技場次數，不發 EXP、Credits 或掉落。</p><button class="primary-button" data-cmd="practice" ${active()?'disabled':''}>前往演練 ${icon('arrow')}</button></section>${[['Random Encounter','隨機遭遇','原站觸發接口目前停用'],['Ring of Blood','血之環','資格、成本與怪物規格待施工'],['Item World','裝備世界','與 IW 等級、鍛造上限整合後開放']].map(([en,title,desc])=>`<section class="panel activity-card">${icon('lock')}<div class="eyebrow">${en}</div><h2>${title}</h2><p>${desc}。未實作前不扣費、不模擬獎勵。</p><span class="tag">保留範圍 · 尚未施工</span></section>`).join('')}</div>`;}

function suppliesView(){if(ui.supplyProduct==='fragments')return fragmentSuppliesView();const q=quoteHealthPurchase(game,ui.supplyQty,game.supplies.revision),last=game.supplies.lastPurchase;return `${heading('THE APOTHECARY','營地補給','將挑戰所得，換成下一趟旅程的準備',`<span class="version-tag">NPC · 本機 Credits</span>`)}${supplyProductSelector()}<div class="supply-layout"><section class="panel supply-main"><div class="supply-item"><div class="potion-vial">${icon('heart')}<span></span></div><div><div class="eyebrow">HEALTH POTION</div><h2>生命藥水</h2><p>新系列恢復 100% 基礎 HP，最多回至上限。<br>0 內部時間，40 道具／一般行動冷卻。</p><span class="tag gold">${SUPPLY_POLICY.unitPrice} Credits / 瓶</span> <span class="tag">NPC 常備供應</span></div></div><div class="supply-order"><label for="supply-quantity">購買數量 <small>單次 1–99,999</small></label><div class="supply-quantity"><input id="supply-quantity" type="number" min="1" max="99999" step="1" value="${esc(ui.supplyQty)}" aria-label="生命藥水購買數量">${[1,5,10].map(n=>`<button class="subtle-button" data-supply-quantity="${n}">${n} 瓶</button>`).join('')}</div><div class="supply-total"><span>本次合計</span><strong>${Number.isSafeInteger(ui.supplyQty)&&ui.supplyQty>=1&&ui.supplyQty<=SUPPLY_POLICY.maxQuantity?(ui.supplyQty*SUPPLY_POLICY.unitPrice).toLocaleString():'—'} <small>Credits</small></strong></div><button class="primary-button" data-cmd="supply-review" ${q.ok?'':'disabled'}>${icon('bag')}檢查購買明細</button><p class="supply-status">${q.ok?'確認後才扣 Credits 並增加藥水；取消不改進度。':esc(q.error)}</p></div></section><aside class="supply-side"><section class="panel supply-pouch"><div class="eyebrow">YOUR PROVISIONS</div><h2>行囊與餘額</h2><div class="supply-row"><span>Credits</span><strong>${game.player.credits.toLocaleString()}</strong></div><div class="supply-row"><span>生命藥水</span><strong>${game.potions.health.toLocaleString()} 瓶</strong></div><div class="supply-row"><span>魔力藥水</span><strong>${game.potions.mana.toLocaleString()} 瓶</strong></div><div class="supply-row fragment-balance"><span>Soul Fragment</span><strong>${statText(game.soulbinding.fragments)} 枚</strong></div>${last?`<div class="supply-receipt"><small>最近一筆 · #${last.revision}</small><p>生命藥水 ×${last.quantity.toLocaleString()}<br>已支付 ${last.total.toLocaleString()} Credits</p></div>`:''}<button class="subtle-button" data-nav="activities">${icon('camp')}返回競技場與活動</button></section><section class="panel supply-boundary"><h3>補給規則</h3><p>價格與生命補給的常備來源來自公開 NPC 規則。沒有玩家掛單、折價權益或虛構庫存。</p><p>Soul Fragment 可切換上方商品購買。魔力補給與其餘商品的供應來源仍待核對；目前不能購買或賣出。戰鬥及波次暫停中均不能交易。</p><a href="./docs/SUPPLIES.md" target="_blank" rel="noopener">查看來源與本機帳本規格 ↗</a></section></aside></div>`;}
function render(){visitTrainingIfReady(Date.now());const focused=document.activeElement,focusData=focused?.dataset?.action,roster=$('.enemies-many'),enemyViewport=roster?{scrollLeft:roster.scrollLeft,target:roster.querySelector('[aria-pressed="true"]')?.dataset.target}:null;$('#app').innerHTML=`<div class="shell"><aside class="rail"><div class="brand-mark"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M13 16 32 49 51 16M21 16l11 20 11-20M32 7v12M25 11h14"/></svg></div><nav class="rail-nav" aria-label="主要導覽">${navs.map(([key,ico,text])=>`<button class="nav-button ${ui.view===key?'active':''}" data-nav="${key}" ${ui.view===key?'aria-current="page"':''}>${icon(ico)}<span>${text}</span></button>`).join('')}</nav><div class="rail-bottom"><div class="rail-version">HV 0.91 · PROTOTYPE</div><button class="nav-button" data-cmd="settings" aria-label="設定">${icon('gear')}</button></div></aside><div class="main-shell">${header()}<main class="content">${historyUpgradePending?`<section class="retention-banner"><span>完整舊檔尚未替換；目前僅供檢視</span><button class="subtle-button" data-cmd="audit-review">匯出與確認保存格式</button></section>`:''}${({battle:battleView,armory:armoryView,character:characterView,activities:activitiesView,supplies:suppliesView,training:trainingView,rules:rulesView}[ui.view])()}${footer()}</main></div></div>`;if(historyUpgradePending){$('#app').querySelectorAll('button').forEach(b=>{if(auditBlocks(b))b.disabled=true;});$('#app').querySelectorAll('[data-protection-item]').forEach(input=>{input.disabled=true;});}if(focusData)document.querySelector(`[data-action="${focusData}"]`)?.focus({preventScroll:true});restoreEnemyViewport(enemyViewport);renderModal();}
let importReadToken=null;
function clearImportPreview(){ui.importGame=null;ui.importArchiveRaw=null;ui.importLegacy=false;}
function openModal(type){importReadToken=null;if(type!=='import')clearImportPreview();ui.modal=type;renderModal();setTimeout(()=>$('#overlays button:not([disabled])')?.focus(),0)}
function closeModal(){importReadToken=null;clearImportPreview();ui.modal=null;ui.pendingTraining=null;ui.trainingError='';ui.pendingFragment=null;ui.pendingSoulbind=null;ui.soulbindProtectionConfirmed=false;ui.soulbindError='';renderModal()}
function renderModal(){let inner='';if(!ui.modal){$('#overlays').innerHTML='';return;}if(ui.modal==='audit-upgrade'){inner=`<div class="eyebrow">SAVE RETENTION UPGRADE</div><h2>讓長期進度保持可保存</h2><p>新版改用有界紀錄：最多 128 筆近期指令結果、64 場近期戰鬥摘要與 100 行近期戰鬥紀事；較早勝負保留為累計。競技場保留最近一次入場及目前系列明細。</p><div class="notice-box">角色、EXP、Credits、裝備、藥水、已用次數及進行中的戰鬥結果不重算。舊指令結果過期後只會拒絕重送，不會重發獎勵。</div><p style="margin-top:13px">確認後，舊詳細紀錄會依此範圍縮短。建議先下載完整原檔；瀏覽器可能無法同時容納完整備份。進度仍只保存在這個瀏覽器；同一份進度請只在一個分頁操作。</p><div class="modal-footer"><button class="subtle-button" data-cmd="export-archive">下載完整舊檔</button><button class="subtle-button" data-cmd="audit-decline">先保留舊檔</button><button class="primary-button" data-cmd="audit-accept">確認採用近期保存</button></div>`;}else if(ui.modal==='welcome'){inner=`<div class="modal-symbol">${icon('moon')}</div><div class="eyebrow">WELCOME TO VESPER</div><h2>在暮色中，開始你的旅程</h2><p>這是 Persistent 0.91 規則研究的可玩原型：原創畫面與手動戰鬥，配上裝備比較和角色調整。</p><div class="notice-box">進度只存在這個瀏覽器。清除網站資料、無痕模式或更換裝置可能讓進度消失。設定中可匯出存檔備份。</div><p style="margin-top:14px">演練數值暫定，尚非原版完整還原。沒有線上帳號、真實市場或原站加成。</p><div class="modal-footer"><button class="primary-button" data-cmd="welcome-accept">我了解，進入暮界 ${icon('arrow')}</button></div>`;}else if(ui.modal==='settings'){inner=`<div class="eyebrow">SETTINGS & SAVE</div><h2>設定與本機存檔</h2><p>目前存檔只保存在此瀏覽器，不會自動同步到其他裝置。</p><div class="settings-row"><span>動畫表現<small>只改變呈現，不影響規則與行動次數</small></span><button class="subtle-button" data-cmd="toggle-motion">${prefs.motion?'已開啟':'已關閉'}</button></div><div class="settings-row"><span>下載備份<small>包含角色、裝備及近期戰鬥紀錄</small></span><button class="subtle-button" data-cmd="export">${icon('download')}匯出存檔</button></div><div class="settings-row"><span>從檔案恢復<small>匯入前會再次確認替換目前進度</small></span><button class="subtle-button" data-cmd="choose-import">${icon('upload')}匯入存檔</button></div>${migrationArchiveRaw?`<div class="settings-row"><span>升級前完整原檔<small>只在本頁開啟期間提供，請下載自行保存</small></span><button class="subtle-button" data-cmd="export-archive">${icon('download')}下載舊檔</button></div>`:''}<div class="settings-row"><span>重新開始演練存檔<small>將重設本機角色、裝備和演練紀錄</small></span><button class="danger-button" data-cmd="confirm-reset">重新開始</button></div>${loadWarning?`<div class="notice-box">${esc(loadWarning)}</div>`:''}<input type="file" id="import-file" accept="application/json,.json" class="sr-only" aria-label="選擇存檔 JSON"><div class="modal-footer"><button class="primary-button" data-cmd="close-modal">完成</button></div>`;}else if(ui.modal==='help'){inner=`<div class="eyebrow">A SINGLE ACTION, A CLEAR RESULT</div><h2>掌握每一次行動</h2><ul><li>先點選敵人，再點底部技能立即執行。左右方向鍵可切换目標。數字鍵 1–7 對應技能，H / M 使用藥水</li><li>探查前只顯示生命比例。等級、精確生命及抗性須消耗探查行動取得</li><li>新戰鬥的法術消耗按角色等級計算；自然 MP／SP 只在 tick 恢復。靈動架式啟動行動不恢復</li><li>行動數、每 100 u 的 tick 和清怪波次各自累積。道具使用為 0 u，但仍消耗數量及道具冷卻</li><li>清空一波後，點擊繼續或按空白鍵進入下一波。等待、關閉頁面或重載不推進戰鬥，也不能離開戰鬥換裝；波次暫停中須先繼續，再選撤退</li><li>整個戰鬥系列結束後，HP／MP／SP 即時回滿；波次之間不回滿。藥水、OC 與獎勵不會因此增加</li><li>目前全部平衡數值以規則帳中的來源和暫定標記為準</li></ul><div class="modal-footer"><button class="primary-button" data-cmd="close-modal">準備好了</button></div>`;}else if(ui.modal==='actions-help'){inner=`<div class="eyebrow">ACTIONS & REQUIREMENTS</div><h2>技能與冷卻說明</h2><div class="action-reference">${listAvailableActions(game).filter(a=>a.id!=='flee').map(a=>`<section><h3>${icon(actionIcons[a.id])}${esc(a.name)} <span>${esc(a.cost)}</span></h3><p>${esc(a.description)}</p>${a.reason?`<small>${esc(a.reason)}</small>`:''}</section>`).join('')}</div><div class="modal-footer"><button class="primary-button" data-cmd="close-modal">返回戰鬥</button></div>`;}else if(ui.modal==='log'){inner=`<div class="eyebrow">BATTLE CHRONICLE</div><h2>近期戰鬥紀事</h2><p>只記錄已完成的結算，不預告敵人決策。最多保留近期 100 行；本系列已有 ${esc(game.battle?.logOmitted||0)} 行較早紀事不再保留。</p><div class="full-log">${logMarkup(true)}</div><div class="modal-footer"><button class="primary-button" data-cmd="close-modal">返回</button></div>`;}else if(ui.modal==='enter-arena'){const a=previewActivities(game.activities,game.player.level,Date.now()).find(x=>x.id===ui.pendingArena);inner=`<div class="eyebrow">DAILY ARENA ENTRY</div><h2>${esc(a?.name)}</h2><p>${a?.rounds} 波，共 ${a?.monsterCount} 隻。入場即消耗今日挑戰次數，失敗或撤退也計入；UTC 00:00 重置。</p><div class="notice-box">體力 ${a?.stamina.toFixed(2)}，需要至少 2。每個勝利波次消耗 0.03（Great）或 0.02（Normal）。EXP 逐波结算，${a?.clears?'重複':'首次'}通關獎勵 ${a?.nextCredits} Credits 與一件樣本池裝備。</div><p style="margin-top:13px">怪物本體／PL100、裝備抽取權重與 EXP 取整仍為明示候選。沒有原站連動加成或替代補償。</p><div class="modal-footer"><button class="subtle-button" data-cmd="close-modal">先整備</button><button class="primary-button" data-cmd="arena-confirm" ${a?.eligible?'':'disabled'}>確認入場</button></div>`;}else if(ui.modal==='enter-grindfest'){inner=grindfestEntryMarkup();}else if(ui.modal==='vitals'){const q=ui.pendingVital;inner=`<div class="eyebrow">UPDATE VITAL FORMULAS</div><h2>採用來源資源候選式？</h2><div class="stat-table">${[['maxHp','HP'],['maxMp','MP'],['maxSp','SP']].map(([key,label])=>`<div class="stat-line"><span>${label} 上限</span><strong>${q.before[key]}</strong><em>${q.after[key]}</em></div>`).join('')}</div><p style="margin-top:14px">右欄為目前屬性與已裝配能力套用新公式後的上限。魔力等上限可能降低；確認後三資源依新上限於戰外回滿。</p><div class="notice-box">不改屬性、EXP、AP、裝備、Credits 或藥水。此介面不提供切回舊模型，可先下載備份。公開公式與最終取整仍為候選規格。</div><div class="modal-footer"><button class="subtle-button" data-cmd="export">先匯出備份</button><button class="subtle-button" data-cmd="close-modal">保留舊模型</button><button class="primary-button" data-cmd="vitals-confirm">確認採用新公式</button></div>`;}else if(ui.modal==='ability-buy'){const q=ui.pendingAbility;inner=`<div class="eyebrow">LEARN ABILITY</div><h2>學習 ${esc(ALL_ABILITIES[q.id].name)}？</h2><div class="notice-box">${q.fromRank} → ${q.toRank} 階<br>消耗 ${q.cost} AP；${q.id==='betterCure'?`裝配後治療 ${cureHealingAmount({baseHp:getStats(game).baseHp,level:game.player.level,potencyPercent:q.potencyPercent})} HP（目前 ${getCureProfile(game).amount}）；冷卻 ${q.cooldown} 行動<br>效力 ${q.potencyPercent}，熟練度 0 樣本；成長未接入`:`裝配後增加 ${q.bonusPercent}% 對應資源上限`}</div><p style="margin-top:13px">學習不會自動裝配。卸下不退 AP；返還須使用有限次數的單項重置。${q.id==='betterCure'?'來源治療候選式可能低於舊樣本，請比較數值；未裝配前維持原效果。':''}最終取整尚未原服驗證。</p><div class="modal-footer"><button class="subtle-button" data-cmd="close-modal">取消</button><button class="primary-button" data-cmd="ability-buy-confirm">確認學習</button></div>`;}else if(ui.modal==='ability-reset'){const id=ui.pendingAbility.id,summary=getAbilitySummary(game);inner=`<div class="eyebrow">RESET ONE ABILITY</div><h2>重置 ${esc(ALL_ABILITIES[id]?.name)}？</h2><p>移除這項能力的所有已學習階級與槽位，返還其投入的 AP。</p><div class="notice-box">將使用 1 次免費單項重置<br>目前剩餘 ${summary.freeSingleResetsRemaining} 次</div><p style="margin-top:13px">次數會記入本機進度；之後重新學習仍須支付 AP。付費重置與全能力重置尚未開放。</p><div class="modal-footer"><button class="subtle-button" data-cmd="close-modal">取消</button><button class="primary-button" data-cmd="ability-reset-confirm">確認重置此能力</button></div>`;}else if(ui.modal==='training-start'||ui.modal==='training-cancel'){inner=trainingModal();}else if(ui.modal==='soul-fragments'){inner=fragmentPurchaseModal();}else if(ui.modal==='soulbind'){inner=soulbindModal();}else if(ui.modal==='supply'){const q=ui.pendingSupply;inner=`<div class="eyebrow">CONFIRM SUPPLIES</div><h2>準備補充生命藥水？</h2><p>NPC 補給 · 每瓶 ${SUPPLY_POLICY.unitPrice} Credits</p><div class="notice-box">數量 ${q.quantity.toLocaleString()} 瓶<br>合計 ${q.total.toLocaleString()} Credits<br>購買後餘額 ${(game.player.credits-q.total).toLocaleString()} Credits</div><p style="margin-top:13px">只使用遊戲內 Credits。確認後立即加入本機行囊；不會回復當前生命、重置冷卻或贈送其他物品。</p><div class="modal-footer"><button class="subtle-button" data-cmd="close-modal">取消</button><button class="primary-button" data-cmd="supply-confirm">確認購買</button></div>`;}else if(ui.modal==='reset'){inner=`<div class="modal-symbol">${icon('reset')}</div><h2>重新開始這份存檔？</h2><p>目前角色、裝備、藥水和演練進度將重設。建議先下載備份；取消後保留原狀。</p><div class="modal-footer"><button class="subtle-button" data-cmd="export">先下載備份</button><button class="subtle-button" data-cmd="close-modal">取消</button><button class="danger-button" data-cmd="reset">確認重設</button></div>`;}else if(ui.modal==='flee'){inner=`<h2>${game.battle?.kind==='grindfest'?'撤離這場 Grindfest？':'撤離這場演練？'}</h2><p>撤退會增加戰鬥時間，途中敵人仍可能出手並造成敗北。戰鬥系列結束後 HP／MP／SP 回滿；已消耗的藥水不補回。已完成波次的 EXP 保留；未完成波次與通關獎勵不發放。${game.battle?.kind==='grindfest'?'已支付的入場與逐波體力不退回。':''}</p><div class="modal-footer"><button class="subtle-button" data-cmd="close-modal">繼續戰鬥</button><button class="primary-button" data-cmd="flee">確認撤退</button></div>`;}else if(ui.modal==='import'){inner=`<h2>以備份取代目前進度？</h2><p>已確認為相容的演練存檔。恢復 ${esc(ui.importGame.player.name)}，第 ${ui.importGame.player.level} 級；${ui.importGame.battle?'包含戰鬥紀錄':'尚未開始演練'}。</p><div class="notice-box">此動作會替換目前本機進度。取消即可保留原狀。${ui.importLegacy?'<br>這是舊版存檔：匯入後採近期紀錄範圍，保留角色與累計成果；詳細舊紀錄請保留原始檔案。':''}</div><div class="modal-footer"><button class="subtle-button" data-cmd="close-modal">取消</button><button class="primary-button" data-cmd="import-confirm">確認恢復</button></div>`;}$('#overlays').innerHTML=`<div class="modal-backdrop" data-backdrop><section class="modal ${['log','soulbind'].includes(ui.modal)?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-heading">${!['welcome','audit-upgrade'].includes(ui.modal)?`<button class="modal-close" data-cmd="close-modal" aria-label="關閉">${icon('close')}</button>`:''}${inner.replace('<h2>','<h2 id="modal-heading">')}</section></div>`;}
function downloadRawSave(raw,archive=false){const blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`vesper-${archive?'legacy-archive':'save'}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存檔已交由瀏覽器下載，請確認檔案已保存');}
function exportSave(){let raw=historyUpgradePending&&migrationArchiveRaw?migrationArchiveRaw:serializeGame(game);if(preserveBadSave&&!migrationArchiveRaw){try{raw=storage.getItem(SAVE_KEY)||raw}catch{}}downloadRawSave(raw,historyUpgradePending);}
function exportArchive(){if(migrationArchiveRaw)downloadRawSave(migrationArchiveRaw,true);else exportSave();}
/** Import/reset stage a save before replacing the visible session or clearing read-only guards. */
async function readImportFile(file){
  const token={};importReadToken=token;
  if(!file)return;
  clearImportPreview();
  if(ui.modal==='import'){ui.modal='settings';renderModal();}
  if(file.size>MAX_LEGACY_RECOVERY_BYTES){toast('檔案超過 20 MB 舊檔恢復上限，未載入');return;}
  try{
    const raw=await file.text();
    if(importReadToken!==token)return;
    const data=restoreGame(raw)||recoverLegacyGame(raw);
    if(!data){toast('檔案格式或規則版本不相容，原存檔未變更');return;}
    ui.importGame=data;ui.importLegacy=JSON.parse(raw).schemaVersion===1;
    ui.importArchiveRaw=ui.importLegacy?raw:null;openModal('import');
  }catch{
    if(importReadToken===token)toast('檔案讀取失敗，原存檔未變更');
  }
}
function replaceGameAfterSave(candidate,{archiveRaw=null,message='進度已保存'}={}){
  const saved=saveLocalGame(storage,candidate,{allowLegacyReplacement:true});
  ui.saveError=saved.error;
  if(!saved.ok){toast(saved.error);return false;}
  game=candidate;
  if(archiveRaw)migrationArchiveRaw=archiveRaw;
  historyUpgradePending=false;preserveBadSave=false;loadWarning='';
  ui.importGame=null;ui.importArchiveRaw=null;ui.importLegacy=false;
  ui.selectedItem=game.equipped.weapon;ui.view=navigateView('battle',{replace:true});
  ui.busy=false;ui.feedback=[];ui.lastAction=null;
  ui.trainingNotice='';ui.trainingError='';ui.pendingTraining=null;
  closeModal();render();toast(saved.warning||message);
  return true;
}
function act(id){if(historyUpgradePending){openModal('audit-upgrade');return;}if(ui.busy||!active())return;ui.busy=true;const before={hp:game.player.hp,mp:game.player.mp,oc:game.player.overcharge,time:game.battle.timeUnits},name=listAvailableActions(game).find(a=>a.id===id)?.name||id;const result=performAction(game,id,game.battle.targetId,nextCommandToken(game));if(result.duplicate){ui.busy=false;toast('此指令已處理，沒有再次執行');return;}if(result.ok){ui.feedback=result.events.filter(e=>e.targetId&&e.amount);ui.lastAction={battleId:game.battle.id,turn:game.battle.turn,name,hp:game.player.hp-before.hp,mp:game.player.mp-before.mp,oc:game.player.overcharge-before.oc,time:game.battle.timeUnits-before.time};persist();render();if(prefs.motion)$('.main-shell')?.classList.add('action-flash');clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>{ui.feedback=[];if(ui.view==='battle')render()},900);}else toast(result.error);setTimeout(()=>{ui.busy=false;render()},250)}
document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b||b.disabled)return;if(auditBlocks(b)){openModal('audit-upgrade');return;}if(b.dataset.nav){ui.view=navigateView(b.dataset.nav);closeModal();render();window.scrollTo({top:0,behavior:'instant'});return;}if(b.dataset.characterTab){ui.characterTab=b.dataset.characterTab==='abilities'?'abilities':'attributes';render();return;}if(b.dataset.abilityBuy){const q=quoteAbilityPurchase(game,b.dataset.abilityBuy);if(q.ok){ui.pendingAbility=q;openModal('ability-buy');}else toast(q.error);return;}if(b.dataset.abilitySlot){const supportive=ALL_ABILITIES[b.dataset.abilitySlot]?.slotType==='supportive';apply((supportive?setSupportiveAbility:setMajorAbility)(game,b.dataset.abilitySlot,game.abilities[supportive?'supportiveSlots':'majorSlots'].indexOf(null)),'能力已裝配，效果已更新');return;}if(b.dataset.abilityUnslot!==undefined){apply((b.dataset.abilityUnslotFamily==='supportive'?clearSupportiveAbility:clearMajorAbility)(game,Number(b.dataset.abilityUnslot)),'能力已卸下，學習階級與 AP 投入保留');return;}if(b.dataset.abilityReset){ui.pendingAbility={id:b.dataset.abilityReset};openModal('ability-reset');return;}if(b.dataset.supplyProduct){ui.supplyProduct=b.dataset.supplyProduct==='fragments'?'fragments':'health';render();return;}if(b.dataset.fragmentQuantity){ui.fragmentQty=Number(b.dataset.fragmentQuantity);render();return;}if(b.dataset.soulbindItem){reviewSoulbind(b.dataset.soulbindItem);return;}if(b.dataset.supplyQuantity){ui.supplyQty=Number(b.dataset.supplyQuantity);render();return;}if(b.dataset.arena){ui.pendingArena=b.dataset.arena;openModal('enter-arena');return;}if(b.dataset.action){act(b.dataset.action);return;}if(b.dataset.target){apply(selectTarget(game,b.dataset.target));return;}if(b.dataset.containerTab){ui.container=b.dataset.containerTab;ui.selectedItem=listOrganizedEquipment(game,{container:ui.container})[0]?.id||ui.selectedItem;render();return;}if(b.dataset.pin){apply(toggleEquipmentPin(game,b.dataset.pin));return;}if(b.dataset.moveItem){const result=moveEquipment(game,b.dataset.moveItem,b.dataset.moveTo);if(result.ok)ui.container=b.dataset.moveTo;apply(result,result.ok?'裝備位置已保存，物品與數值不變':'');return;}if(b.dataset.item){ui.selectedItem=b.dataset.item;render();return;}if(b.dataset.filter){ui.filter=b.dataset.filter;render();return;}if(b.dataset.bench){ui.benchTab=b.dataset.bench;render();return;}if(b.dataset.equip){apply(equipItem(game,b.dataset.equip),'裝備已更換，角色面板已更新');return;}if(b.dataset.attribute){const delta=Number(b.dataset.delta||1),result=spendAttribute(game,b.dataset.attribute,delta);apply(result,result.cost!==undefined?`${attrs[b.dataset.attribute][0]} ${result.from} → ${result.to}；${result.cost>=0?'配置':'返還'} ${Math.abs(result.cost)} EXP`:'屬性已保存');return;}if(b.dataset.lock){const item=game.inventory.find(i=>i.id===b.dataset.lock);if(item){const locked=!item.locked;apply(setItemProtected(game,item.id,locked),locked?'已加入本機保護標記':'已解除本機保護標記')}return;}const cmd=b.dataset.cmd;if(!cmd)return;if(['settings','help','log','actions-help'].includes(cmd)){openModal(cmd);return;}if(cmd==='audit-review'){openModal('audit-upgrade');return;}if(cmd==='audit-decline'){closeModal();render();return;}if(cmd==='audit-accept'){const saved=saveLocalGame(storage,game,{allowLegacyReplacement:true});ui.saveError=saved.error;if(saved.ok){historyUpgradePending=false;preserveBadSave=false;loadWarning='';prefs.onboarded=true;savePrefs();closeModal();render();toast(saved.warning||'保存格式已更新；角色與累計進度保留');}else toast(saved.error);return;}if(cmd==='export-archive'){exportArchive();return;}if(cmd==='vitals-review'){const q=getVitalUpgradeQuote(game);if(q.ok){ui.pendingVital=q;openModal('vitals');}else toast(q.error);return;}if(cmd==='vitals-confirm'){const q=ui.pendingVital;if(!q)return;const r=upgradeVitalModel(game,q.fromModel);if(r.ok){ui.pendingVital=null;closeModal();}apply(r,'已採用來源資源模型；屬性、EXP、道具與配裝不變');return;}if(cmd==='ability-buy-confirm'){const q=ui.pendingAbility;if(!q)return;const r=purchaseAbility(game,q.id,q.fromRank);if(r.ok){ui.pendingAbility=null;closeModal();}apply(r,'能力已學習；裝入 '+(q.id==='betterCure'?'Supportive':'Major')+' 空槽後才會生效');return;}if(cmd==='ability-reset-confirm'){const q=ui.pendingAbility;if(!q)return;const r=resetPurchasedAbility(game,q.id);if(r.ok){ui.pendingAbility=null;closeModal();}apply(r,'已消耗一次免費重置並返還此能力的 AP');return;}if(cmd==='training-start-review'){reviewTraining('start');return;}if(cmd==='training-cancel-review'){reviewTraining('cancel');return;}if(cmd==='training-start-confirm'){confirmTrainingStart();return;}if(cmd==='training-cancel-confirm'){confirmTrainingCancel();return;}if(cmd==='training-refresh'){if(ui.pendingTraining)reviewTraining(ui.pendingTraining.kind);return;}if(cmd==='training-collect'){if(!ui.modal)render();return;}if(cmd==='fragment-review'){reviewFragmentPurchase();return;}if(cmd==='fragment-confirm'){confirmFragmentPurchase();return;}if(cmd==='soulbind-confirm'){confirmSoulbind();return;}if(cmd==='soulbind-refresh'){if(ui.pendingSoulbind)reviewSoulbind(ui.pendingSoulbind.itemId);return;}if(cmd==='shop-fragments'){ui.supplyProduct='fragments';ui.view=navigateView('supplies');closeModal();render();return;}if(cmd==='supply-review'){const q=quoteHealthPurchase(game,ui.supplyQty,game.supplies.revision);if(q.ok){ui.pendingSupply=q;openModal('supply');}else toast(q.error);return;}if(cmd==='supply-confirm'){const q=ui.pendingSupply;if(!q)return;const result=purchaseHealthPotion(game,q.quantity,q.expectedRevision);if(result.ok){ui.pendingSupply=null;closeModal();}apply(result,result.duplicate?'此筆補給已處理':'補給已加入行囊，Credits 已扣除');return;}if(cmd==='close-modal')closeModal();if(cmd==='welcome-accept'){prefs.onboarded=true;savePrefs();closeModal();persist();render();if(historyUpgradePending)openModal('audit-upgrade');else if(loadWarning)toast(loadWarning)}if(cmd==='continue-round'){ui.feedback=[];apply(continueRound(game));}if(cmd==='grindfest-review'){openModal('enter-grindfest');return;}if(cmd==='grindfest-confirm'){if(ui.modal!=='enter-grindfest')return;const result=startGrindfest(game,Date.now());if(result.ok){ui.view=navigateView('battle');ui.feedback=[];ui.lastAction=null;closeModal();}apply(result);return;}if(cmd==='arena-confirm'){const result=startArena(game,ui.pendingArena,Date.now());if(result.ok){ui.view=navigateView('battle');ui.feedback=[];ui.lastAction=null;closeModal();}apply(result);}if(cmd==='practice'){const result=startBattle(game);if(result.ok){ui.view=navigateView('battle');ui.feedback=[];ui.lastAction=null;}apply(result);}if(cmd==='start'){ui.feedback=[];ui.lastAction=null;apply(startBattle(game));}if(cmd==='rest')apply(rest(game),'已確認戰外 HP / MP / SP，藥水與 OC 不變');if(cmd==='toggle-motion'){prefs.motion=!prefs.motion;savePrefs();renderModal()}if(cmd==='export')exportSave();if(cmd==='confirm-reset')openModal('reset');if(cmd==='reset')replaceGameAfterSave(createGame(),{message:'新演練已建立'});if(cmd==='choose-import')$('#import-file').click();if(cmd==='import-confirm')replaceGameAfterSave(ui.importGame,{archiveRaw:ui.importArchiveRaw,message:'備份已恢復'});if(cmd==='confirm-flee')openModal('flee');if(cmd==='flee'){closeModal();act('flee')}});
document.addEventListener('input',event=>{if(event.target.id==='inventory-search'){const pos=event.target.selectionStart;ui.search=event.target.value;render();const input=$('#inventory-search');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('change',async event=>{if(event.target.id==='fragment-quantity'){ui.fragmentQty=Number(event.target.value);render();return;}if(event.target.id==='soulbind-protection-confirm'){if(ui.modal==='soulbind'&&ui.pendingSoulbind?.requiresProtectionConfirmation){ui.soulbindProtectionConfirmed=event.target.checked===true;renderModal();$('#soulbind-protection-confirm')?.focus();}return;}if(event.target.id==='supply-quantity'){ui.supplyQty=Number(event.target.value);render();return;}if(historyUpgradePending&&event.target.dataset.protectionItem){render();openModal('audit-upgrade');return;}if(event.target.dataset.protectionItem){apply(setEquipmentProtection(game,event.target.dataset.protectionItem,event.target.value),'裝備保護狀態已保存');return;}if(event.target.id==='attribute-step'){ui.attributeStep=Number(event.target.value);render();return;}if(event.target.id==='import-file')await readImportFile(event.target.files[0]);});
document.addEventListener('keydown',event=>{if(ui.modal){if(event.key==='Escape'&&!['welcome','audit-upgrade'].includes(ui.modal)){closeModal();return;}if(event.key==='Tab'){const nodes=[...$('#overlays').querySelectorAll('button:not([disabled]),a,input,select')].filter(n=>!n.classList.contains('sr-only'));const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}return;}if(event.repeat||event.ctrlKey||event.altKey||event.metaKey||/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)||ui.view!=='battle')return;if(historyUpgradePending){event.preventDefault();openModal('audit-upgrade');return;}if(event.code==='Space'&&game.battle?.phase==='round-complete'){event.preventDefault();ui.feedback=[];apply(continueRound(game));return;}if(['ArrowLeft','ArrowRight'].includes(event.key)&&active()){const living=game.battle.enemies.filter(e=>e.hp>0),index=living.findIndex(e=>e.id===game.battle.targetId),next=living[(index+(event.key==='ArrowRight'?1:-1)+living.length)%living.length];if(next){event.preventDefault();apply(selectTarget(game,next.id));}return;}const ids=['attack','fire','cure','scan','defend','focus','spirit'];const id=ids[Number(event.key)-1]||(event.key.toLowerCase()==='h'?'healthPotion':event.key.toLowerCase()==='m'?'manaPotion':null);if(id){event.preventDefault();act(id)}});
window.addEventListener('popstate',()=>{ui.view=readView(location.hash);closeModal();render()});
window.addEventListener('pagehide',()=>{if(!preserveBadSave)persist()});
if(typeof window.setInterval==='function')window.setInterval(refreshTrainingClock,1000);
savePrefs();render();if(historyUpgradePending)openModal('audit-upgrade');else if(!prefs.onboarded)openModal('welcome');else if(loadWarning)toast(loadWarning);
